"""Wrong rules, planted one at a time (see `runner.py`, beside this list).

The kernel of the Oracle's conversation: what a phone may send, what waits for the user, what the voice is told
when a call begins, the conversation and its routing.
"""
import runner

RUNS = {
    'vectors': ['test', '--test', 'oracle_conversation_vectors'],
}
P = 'clarp-kernel/src/oracle/phone.rs'
A = 'clarp-kernel/src/oracle/attention.rs'
V = 'clarp-kernel/src/oracle/voice.rs'
R = 'clarp-kernel/src/oracle/routing.rs'
C = 'clarp-kernel/src/oracle/conversation.rs'
T = 'vectors'
# NOT PLANTED, each with its reason:
#   that a long answer goes on only while the voice is not speaking, and only once it has been quiet for a second
#     and a half (the two last conditions of `advance_relay`; taken off the list after their first run, where both
#     were MISSED): each holds what the other holds, but for the very millisecond at which the voice is taken to
#     have fallen silent, and no story may stand on a millisecond.
#   voice.rs: that nobody who speaks no language is told a sentence (`None => String::new()`): a call's beginning
#     asks for the sentence only where languages are told; the arm is there because the function is whole.
#   conversation.rs: a fraction of a millisecond in what the voice sends is cut (`whole`): the voice writes whole
#     milliseconds, and the Python Host would keep a fraction as written, so no story of it can agree.
#   conversation.rs: a cue of a name there is not is left out (`earcons::pcm` says none): the Host asks for the five
#     cues there are.
#   conversation.rs: a result whose names leave no room for a text is not told (`relay_for` says none): the names
#     of a delegation are bounded; the Python Host would end the call there.
#   conversation.rs, routing.rs: the guards for a relay or an action that is not there (`let Some(..) else`,
#     `ok_or(Failed)` on `route.doing`): nothing in the machine reaches them.
#   routing.rs: that a tool's answer without a status is no hand-on (`unwrap_or("")`): written out by the same
#     comparison that is planted.
#   conversation.rs: on which side of a threshold a moment exactly so long after another falls (`<` or `<=`): the
#     Python Host compares fractions of seconds, and the generator refuses every story that is decided on such an
#     edge; the thresholds themselves are planted shorter and longer.
#   conversation.rs: what `to_keep` writes field by field: it is compared whole after every step.
